INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-12442', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-13T13:20:59.322Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wizard Spider](https://attack.mitre.org/groups/G0102) has used scheduled tasks to install [TrickBot](https://attack.mitre.org/software/S0266), using task names to appear legitimate such as WinDotNet, GoogleTask, or Sysnetsf.(Citation: CrowdStrike Grim Spider May 2019) It has also used common document file names for other malware binaries.(Citation: FireEye KEGTAP SINGLEMALT October 2020)", "external_references": [{"description": "John, E. and Carvey, H. (2019, May 30). Unraveling the Spiderweb: Timelining ATT&CK Artifacts Used by GRIM SPIDER. Retrieved May 12, 2020.", "source_name": "CrowdStrike Grim Spider May 2019", "url": "https://www.crowdstrike.com/blog/timelining-grim-spiders-big-game-hunting-tactics/"}, {"description": "Kimberly Goody, Jeremy Kennelly, Joshua Shilko, Steve Elovitz, Douglas Bienstock. (2020, October 28). Unhappy Hour Special: KEGTAP and SINGLEMALT With a Ransomware Chaser. Retrieved October 28, 2020.", "source_name": "FireEye KEGTAP SINGLEMALT October 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/10/kegtap-and-singlemalt-with-a-ransomware-chaser.html"}], "id": "relationship--7e555910-0e1b-403d-a369-e7a2e8e61670", "modified": "2026-07-31T20:48:50.336Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dd2d9ca6-505b-4860-a604-233685b802c7", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12442', 0, 140, '09-mitre-attack', 'retrieved', '867F52BA9FDB823D667D666B4CE248C058283A4EAA666D6B665E0BC9BE2C0C7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
