VALUES ('doc-09-mitre-attack-p0-12448', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-07T16:02:55.040Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wizard Spider](https://attack.mitre.org/groups/G0102) has created and used new accounts within a victim''s Active Directory environment to maintain persistence.(Citation: Mandiant FIN12 Oct 2021)", "external_references": [{"description": "Shilko, J., et al. (2021, October 7). FIN12: The Prolific Ransomware Intrusion Threat Actor That Has Aggressively Pursued Healthcare Targets. Retrieved June 15, 2023.", "source_name": "Mandiant FIN12 Oct 2021", "url": "https://web.archive.org/web/20220313061955/https://www.mandiant.com/sites/default/files/2021-10/fin12-group-profile.pdf"}], "id": "relationship--970860bd-6183-4728-8f34-a5a1ad199655", "modified": "2026-07-31T20:48:50.383Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dd2d9ca6-505b-4860-a604-233685b802c7", "spec_version": "2.1", "target_ref": "attack-pattern--7610cada-1499-41a4-b3dd-46467b68d177", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12448', 0, 83, '09-mitre-attack', 'retrieved', 'AAF44A39FA67FCE3EB05542AB6E81E8EED236B55112889C16F36407C76DCBECE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
