VALUES ('doc-09-mitre-attack-p0-12470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-13T17:16:11.123Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wizard Spider](https://attack.mitre.org/groups/G0102) has used networkdll for network discovery and psfin specifically for financial and point of sale indicators. [Wizard Spider](https://attack.mitre.org/groups/G0102) has also used [AdFind](https://attack.mitre.org/software/S0552), nltest/dclist , and PowerShell script Get-DataInfo.ps1 to enumerate domain computers, including the domain controller.(Citation: FireEye Ryuk and Trickbot January 2019)(Citation: CrowdStrike Grim Spider May 2019)(Citation: FireEye KEGTAP SINGLEMALT October 2020)(Citation: Red Canary Hospital Thwarted Ryuk October 2020)(Citation: DFIR Ryuk''s Return October 2020)(Citation: Mandiant FIN12 Oct 2021)", "external_references": [{"description": "Brian Donohue, Katie Nickels, Paul Michaud, Adina Bodkins, Taylor Chapman, Tony Lambert, Jeff Felling, Kyle Rainey, Mike Haag, Matt Graeber, Aaron Didier.. (2020, October 29). A Bazar start: How one hospital thwarted a Ryuk ransomware outbreak. Retrieved October 30, 2020.", "source_name": "Red Canary Hospital Thwarted Ryuk October 2020", "url": "https://redcanary.com/blog/how-one-hospital-thwarted-a-ryuk-ransomware-outbreak/"}, {"description": "Goody, K., et al (2019, January 11). A Nasty Trick: From Credential Theft Malware to Business Disruption. Retrieved May 12, 2020.", "source_name": "FireEye Ryuk and Trickbot January 2019", "url": "https://www.fireeye.com/blog/threat-research/2019/01/a-nasty-trick-from-credential-theft-malware-to-business-disruption.html"}, {"description": "John, E. and Carvey, H. (2019, May 30). Unraveling the Spiderweb: Timelining ATT&CK Artifacts Used by GRIM SPIDER. Retrieved May 12, 2020.", "source_name": "CrowdStrike Grim Spider May 2019", "url": "https://www.crowdstrike.com/blog/timelining-grim-spiders-big-game-hunting-tactics/"}, {"description": "Kimberly Goody, Jeremy Kennelly, Joshua Shilko, Steve Elovitz, Douglas Bienstock. (2020, October 28). Unhappy Hour Special: KEGTAP and SINGLEMALT With a Ransomware Chaser. Retrieved October 28, 2020.", "source_name": "FireEye KEGTAP SINGLEMALT October 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/10/kegtap-and-singlemalt-with-a-ransomware-chaser.html"}, {"description": "Shilko, J., et al. (2021, October 7). FIN12: The Prolific Ransomware Intrusion Threat Actor That Has Aggressively Pursued Healthcare Targets. Retrieved June 15, 2023.", "source_name": "Mandiant FIN12 Oct 2021", "url": "https://web.archive.org/web/20220313061955/https://www.mandiant.com/sites/default/files/2021-10/fin12-group-profile.pdf"}, {"description": "The DFIR Report. (2020, October 8). Ryuk’s Return. Retrieved October 9, 2020.", "source_name": "DFIR Ryuk''s Return October 2020", "url": "https://thedfirreport.com/2020/10/08/ryuks-return/"}], "id": "relationship--df13cae2-4e20-4e89-ae60-6bd8b99e2342", "modified": "2026-07-31T20:48:50.560Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dd2d9ca6-505b-4860-a604-233685b802c7", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12470', 0, 302, '09-mitre-attack', 'retrieved', 'B03E04F26F0229551E653B0E87954E9E2EFD3F2C5D2B1371009D76674BEC01F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
