INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-12472', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-10T16:24:47.347Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wizard Spider](https://attack.mitre.org/groups/G0102) has used [Systeminfo](https://attack.mitre.org/software/S0096) and similar commands to acquire detailed configuration information of a victim''s machine. [Wizard Spider](https://attack.mitre.org/groups/G0102) has also utilized the PowerShell cmdlet `Get-ADComputer` to collect DNS hostnames, last logon dates, and operating system information from Active Directory.(Citation: DFIR Ryuk''s Return October 2020)(Citation: Mandiant FIN12 Oct 2021)", "external_references": [{"description": "Shilko, J., et al. (2021, October 7). FIN12: The Prolific Ransomware Intrusion Threat Actor That Has Aggressively Pursued Healthcare Targets. Retrieved June 15, 2023.", "source_name": "Mandiant FIN12 Oct 2021", "url": "https://web.archive.org/web/20220313061955/https://www.mandiant.com/sites/default/files/2021-10/fin12-group-profile.pdf"}, {"description": "The DFIR Report. (2020, October 8). Ryuk’s Return. Retrieved October 9, 2020.", "source_name": "DFIR Ryuk''s Return October 2020", "url": "https://thedfirreport.com/2020/10/08/ryuks-return/"}], "id": "relationship--e24411cf-6274-4b6b-87b4-b90b01146c8d", "modified": "2026-07-31T20:48:50.577Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dd2d9ca6-505b-4860-a604-233685b802c7", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12472', 0, 132, '09-mitre-attack', 'retrieved', '205D9A6E78977FCA27FAEA6749BC81421394F98C2B9C7E236E10128470AE23B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
