VALUES ('doc-09-mitre-attack-p0-12507', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:25:10.228Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Velvet Ant](https://attack.mitre.org/groups/G1047) has used malicious DLLs executed via legitimate EXE files through DLL search order hijacking to launch follow-on payloads such as [PlugX](https://attack.mitre.org/software/S0013).(Citation: Sygnia VelvetAnt 2024A)", "external_references": [{"description": "Sygnia Team. (2024, June 3). China-Nexus Threat Group ‘Velvet Ant’ Abuses F5 Load Balancers for Persistence. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024A", "url": "https://www.sygnia.co/blog/china-nexus-threat-group-velvet-ant/"}], "id": "relationship--1236d556-1b4a-4d0f-96b2-cf036b30ca17", "modified": "2026-07-31T18:48:23.744Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--e1fc262c-dad2-4b82-abda-5f08dd134971", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12507', 0, 83, '09-mitre-attack', 'retrieved', '5A0BD88EC5AD9ACAFDE2E3954E40563A7544EB82F73F45DB18B9C33FBA7CA752', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
