VALUES ('doc-09-mitre-attack-p0-12508', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:45:56.680Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Velvet Ant](https://attack.mitre.org/groups/G1047) sent commands to compromised F5 BIG-IP devices in an encoded format requiring a passkey before interpretation and execution.(Citation: Sygnia VelvetAnt 2024A)", "external_references": [{"description": "Sygnia Team. (2024, June 3). China-Nexus Threat Group ‘Velvet Ant’ Abuses F5 Load Balancers for Persistence. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024A", "url": "https://www.sygnia.co/blog/china-nexus-threat-group-velvet-ant/"}], "id": "relationship--2d5cfd77-4222-48d0-b9f0-90487caeb952", "modified": "2026-07-31T18:48:23.769Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--e1fc262c-dad2-4b82-abda-5f08dd134971", "spec_version": "2.1", "target_ref": "attack-pattern--cc7b8c4e-9be0-47ca-b0bb-83915ec3ee2f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12508', 0, 80, '09-mitre-attack', 'retrieved', '821B51AD07070B90A5661FCF5209234EBBFF579C40CCB645DCA9C6CD8084DE4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
