VALUES ('doc-09-mitre-attack-p0-12509', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:35:20.679Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Velvet Ant](https://attack.mitre.org/groups/G1047) used the `wmiexec.py` tool within [Impacket](https://attack.mitre.org/software/S0357) for remote process execution via WMI.(Citation: Sygnia VelvetAnt 2024A)", "external_references": [{"description": "Sygnia Team. (2024, June 3). China-Nexus Threat Group ‘Velvet Ant’ Abuses F5 Load Balancers for Persistence. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024A", "url": "https://www.sygnia.co/blog/china-nexus-threat-group-velvet-ant/"}], "id": "relationship--341a8145-4d62-4126-a18d-10976d08d920", "modified": "2026-07-31T18:48:23.798Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--e1fc262c-dad2-4b82-abda-5f08dd134971", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12509', 0, 74, '09-mitre-attack', 'retrieved', '52A75BA53FBBB629705AADBF87F31A02BD08FADA1ACF2F11BA73F2079A5FDC43', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
