VALUES ('doc-09-mitre-attack-p0-12524', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T19:48:34.955Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Velvet Ant](https://attack.mitre.org/groups/G1047) exploited CVE-2024-20399 in Cisco Switches to which the threat actor was already able to authenticate in order to escape the NX-OS command line interface and gain access to the underlying operating system for arbitrary command execution.(Citation: Sygnia VelvetAnt 2024B)", "external_references": [{"description": "Sygnia Team. (2024, July 1). China-Nexus Threat Group ‘Velvet Ant’ Exploits Cisco Zero-Day (CVE-2024-20399) to Compromise Nexus Switch Devices – Advisory for Mitigation and Response. Retrieved March 14, 2025.", "source_name": "Sygnia VelvetAnt 2024B", "url": "https://www.sygnia.co/threat-reports-and-advisories/china-nexus-threat-group-velvet-ant-exploits-cisco-0-day/"}], "id": "relationship--c875bba4-cfc1-439d-919f-ed0997b9288b", "modified": "2026-07-31T18:48:24.135Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--e1fc262c-dad2-4b82-abda-5f08dd134971", "spec_version": "2.1", "target_ref": "attack-pattern--fe926152-f431-4baf-956c-4ad3cb0bf23b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12524', 0, 107, '09-mitre-attack', 'retrieved', '987CAA888BB9B5B658859FD6B92ACECDF5649DCBA0E3E4943ED97795ABCCA49F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
