VALUES ('doc-09-mitre-attack-p0-12626', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T20:24:00.576Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VOID MANTICORE](https://attack.mitre.org/groups/G1055) has utilized PowerShell scripts that run without notifying the user of its execution to include `-nop -w hidden- ep bypass -enc`.(Citation: FBI IC3 Flash VOID MANTICORE Handala Hack March 2026)", "external_references": [{"description": "FBI. (2026, March 20). FBI Flash: FLASH-20260320-001:Government of Iran Cyber Actors Deploy Telegram C2 to Push Malware to Identified Targets. Retrieved April 20, 2026.", "source_name": "FBI IC3 Flash VOID MANTICORE Handala Hack March 2026", "url": "https://www.ic3.gov/CSA/2026/260320.pdf"}], "id": "relationship--2798da1f-3e11-43d3-b581-2b5e0926feb5", "modified": "2026-07-31T18:48:25.370Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--ebd7ce77-c9ba-4fba-bb28-58296ac66559", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12626', 0, 99, '09-mitre-attack', 'retrieved', '6294E38C81711AAC85C9AD3532B3986490BF83E4E25B81394803832E3637776B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
