VALUES ('doc-09-mitre-attack-p0-12667', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T18:03:22.300Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VOID MANTICORE](https://attack.mitre.org/groups/G1055) has utilized credential stuffing attacks to obtain initial access to victim environments.(Citation: Domain Tools Handala Hack Karma Homeland Justice MOIS April 2026)", "external_references": [{"description": "DomainTools Investigations. (2026, April 6). Handala: MOIS Linked Cyber Influence Ecosystem Threat Intelligence Assessment. Retrieved April 20, 2026.", "source_name": "Domain Tools Handala Hack Karma Homeland Justice MOIS April 2026", "url": "https://dti.domaintools.com/research/handala-mois-linked-cyber-influence-ecosystem-threat-intelligence-assessment"}], "id": "relationship--e932046e-705d-4eb0-9cdd-8d35675db540", "modified": "2026-07-31T18:48:26.104Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--ebd7ce77-c9ba-4fba-bb28-58296ac66559", "spec_version": "2.1", "target_ref": "attack-pattern--b2d03cea-aec1-45ca-9744-9ee583c1e1cc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12667', 0, 86, '09-mitre-attack', 'retrieved', '556F90F27F7C453673FBF8DB9EA872EE30FB19CDE0F658A3906C37C5ED7D9925', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
