VALUES ('doc-09-mitre-attack-p0-12668', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T17:49:54.597Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VOID MANTICORE](https://attack.mitre.org/groups/G1055) has created Telegram Accounts.(Citation: FBI IC3 Flash VOID MANTICORE Handala Hack March 2026) [VOID MANTICORE](https://attack.mitre.org/groups/G1055) has also leveraged online personas such as Handala Hack, Karma, and Homeland Justice on social media to include Telegram.(Citation: Check Point VOID MANTICORE Handala Hack March 2026)(Citation: SPECOPS Outpost24 Handala Hack Stryker March 2026)(Citation: DOJ FBI Handala Hack March 2026) [VOID MANTICORE](https://attack.mitre.org/groups/G1055) has established and maintained social media accounts on Twitter/X and Telegram to amplify operational claims and stolen data disclosures.(Citation: Domain Tools Handala Hack Karma Homeland Justice MOIS April 2026)", "external_references": [{"description": "Check Point Research. (2026, March 12). “Handala Hack” – Unveiling Group’s Modus Operandi. Retrieved April 20, 2026.", "source_name": "Check Point VOID MANTICORE Handala Hack March 2026", "url": "https://research.checkpoint.com/2026/handala-hack-unveiling-groups-modus-operandi/"}, {"description": "David Ketler. (2026, March 30). Stryker Cyber-Attack: What we Know so Far About the Remote Wipe Attack. Retrieved April 20, 2026.", "source_name": "SPECOPS Outpost24 Handala Hack Stryker March 2026", "url": "https://specopssoft.com/blog/stryker-cyber-attack-what-we-know-remote-wipe/"}, {"description": "DOJ/FBI. (2026, March 19). Case 1:26-mj-00683-CDA: Affidavit in Support of Seizure Warrant: In the Matter of the Seizure of Domain Names Justicehomeland[.]org; karmabelow80[.]org; handala-hack[.]to; and handala-redwatned[.]to. Retrieved April 20, 2026.", "source_name": "DOJ FBI Handala Hack March 2026", "url": "https://www.justice.gov/opa/media/1431956/dl?inline"}, {"description": "DomainTools Investigations. (2026, April 6). Handala: MOIS Linked Cyber Influence Ecosystem Threat Intelligence Assessment. Retrieved April 20, 2026.", "source_name": "Domain Tools Handala Hack Karma Homeland Justice MOIS April 2026", "url": "https://dti.domaintools.com/research/handala-mois-linked-cyber-influence-ecosystem-threat-intelligence-assessment"}, {"description": "FBI. (2026, March 20). FBI Flash: FLASH-20260320-001:Government of Iran Cyber Actors Deploy Telegram C2 to Push Malware to Identified Targets. Retrieved April 20, 2026.", "source_name": "FBI IC3 Flash VOID MANTICORE Handala Hack March 2026", "url": "https://www.ic3.gov/CSA/2026/260320.pdf"}], "id": "relationship--ea78d30b-6678-475a-93c6-24c1cb7ccf54", "modified": "2026-07-31T18:48:26.120Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--ebd7ce77-c9ba-4fba-bb28-58296ac66559", "spec_version": "2.1", "target_ref": "attack-pattern--b1ccd744-3f78-4a0e-9bb2-2002057f7928", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12668', 0, 288, '09-mitre-attack', 'retrieved', '194F9B0AEAB2608E21C960E39153C8C44F6B15A17D49B9391F8FA9C5A769021A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
