VALUES ('doc-09-mitre-attack-p0-12758', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-01T15:28:06.628Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HEXANE](https://attack.mitre.org/groups/G1001) has acquired, and sometimes customized, open source tools such as [Mimikatz](https://attack.mitre.org/software/S0002), [Empire](https://attack.mitre.org/software/S0363), VNC remote access software, and DIG.net.(Citation: Kaspersky Lyceum October 2021)(Citation: SecureWorks August 2019)(Citation: Zscaler Lyceum DnsSystem June 2022)", "external_references": [{"description": "Kayal, A. et al. (2021, October). LYCEUM REBORN: COUNTERINTELLIGENCE IN THE MIDDLE EAST. Retrieved June 14, 2022.", "source_name": "Kaspersky Lyceum October 2021", "url": "https://vblocalhost.com/uploads/VB2021-Kayal-etal.pdf"}, {"description": "SecureWorks 2019, August 27 LYCEUM Takes Center Stage in Middle East Campaign Retrieved. 2019/11/19 ", "source_name": "SecureWorks August 2019", "url": "https://www.secureworks.com/blog/lyceum-takes-center-stage-in-middle-east-campaign"}, {"description": "Shivtarkar, N. and Kumar, A. (2022, June 9). Lyceum .NET DNS Backdoor. Retrieved June 23, 2022.", "source_name": "Zscaler Lyceum DnsSystem June 2022", "url": "https://www.zscaler.com/blogs/security-research/lyceum-net-dns-backdoor"}], "id": "relationship--86a7e0a4-4fbd-4355-9428-f0b79249d225", "modified": "2026-07-31T20:48:51.822Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f29b7c5e-2439-42ad-a86f-9f8984fafae3", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12758', 0, 133, '09-mitre-attack', 'r