VALUES ('doc-09-mitre-attack-p0-12797', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-25T17:34:22.283Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Daggerfly](https://attack.mitre.org/groups/G1034) is associated with several supply chain compromises using malicious updates to compromise victims.(Citation: ESET EvasivePanda 2023)(Citation: ESET EvasivePanda 2024)", "external_references": [{"description": "Ahn Ho, Facundo Muñoz, & Marc-Etienne M.Léveillé. (2024, March 7). Evasive Panda leverages Monlam Festival to target Tibetans. Retrieved July 25, 2024.", "source_name": "ESET EvasivePanda 2024", "url": "https://www.welivesecurity.com/en/eset-research/evasive-panda-leverages-monlam-festival-target-tibetans/"}, {"description": "Facundo Muñoz. (2023, April 26). Evasive Panda APT group delivers malware via updates for popular Chinese software. Retrieved July 25, 2024.", "source_name": "ESET EvasivePanda 2023", "url": "https://www.welivesecurity.com/2023/04/26/evasive-panda-apt-group-malware-updates-popular-chinese-software/"}], "id": "relationship--c043fd01-53bf-43ec-982d-44359c47d905", "modified": "2026-07-31T18:48:27.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f3be6240-f68e-47e1-90d2-ad8f3b3bb8a6", "spec_version": "2.1", "target_ref": "attack-pattern--bd369cd9-abb8-41ce-b5bb-fff23ee86c00", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12797', 0, 107, '09-mitre-attack', 'retrieved', '306D5D2372A08057B074E5BBB4EBC6E1D51B36C7F8758D7BB9192C46F9E05965', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
