VALUES ('doc-09-mitre-attack-p0-12867', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-05T18:53:03.497Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Magic Hound](https://attack.mitre.org/groups/G0059) has used the Telegram API `sendMessage` to relay data on compromised devices.(Citation: Google Iran Threats October 2021)", "external_references": [{"description": "Bash, A. (2021, October 14). Countering threats from Iran. Retrieved January 4, 2023.", "source_name": "Google Iran Threats October 2021", "url": "https://blog.google/threat-analysis-group/countering-threats-iran/"}], "id": "relationship--043ea873-396a-4ba8-a3e3-1f9af11c986e", "modified": "2026-07-31T18:48:28.023Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f9d6633a-55e6-4adc-9263-6ae080421a13", "spec_version": "2.1", "target_ref": "attack-pattern--40597f16-0963-4249-bf4c-ac93b7fb9807", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12867', 0, 71, '09-mitre-attack', 'retrieved', 'EC7446701C6600453D12A7CC275861787C72E31B2E086FBD9CFFFEE3685BA590', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
