VALUES ('doc-09-mitre-attack-p0-12909', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Magic Hound](https://attack.mitre.org/groups/G0059) malware has obtained the victim username and sent it to the C2 server.(Citation: Unit 42 Magic Hound Feb 2017)(Citation: DFIR Report APT35 ProxyShell March 2022)(Citation: DFIR Phosphorus November 2021)", "external_references": [{"description": "DFIR Report. (2021, November 15). Exchange Exploit Leads to Domain Wide Ransomware. Retrieved January 5, 2023.", "source_name": "DFIR Phosphorus November 2021", "url": "https://thedfirreport.com/2021/11/15/exchange-exploit-leads-to-domain-wide-ransomware/"}, {"description": "DFIR Report. (2022, March 21). APT35 Automates Initial Access Using ProxyShell. Retrieved May 25, 2022.", "source_name": "DFIR Report APT35 ProxyShell March 2022", "url": "https://thedfirreport.com/2022/03/21/apt35-automates-initial-access-using-proxyshell"}, {"description": "Lee, B. and Falcone, R. (2017, February 15). Magic Hound Campaign Attacks Saudi Targets. Retrieved December 27, 2017.", "source_name": "Unit 42 Magic Hound Feb 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/02/unit42-magic-hound-campaign-attacks-saudi-targets/"}], "id": "relationship--7ac10827-9bf6-4d60-aa16-9f2d2930b373", "modified": "2026-07-31T18:48:28.700Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f9d6633a-55e6-4adc-9263-6ae080421a13", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12909', 0, 138, '09-mitre-attack', 'retrieved', '27DCC12A5A94E51