VALUES ('doc-09-mitre-attack-p0-12910', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-18T13:34:21.144Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Magic Hound](https://attack.mitre.org/groups/G0059) granted compromised email accounts read access to the email boxes of additional targeted accounts. The group then was able to authenticate to the intended victim''s OWA (Outlook Web Access) portal and read hundreds of email communications for information on Middle East organizations.(Citation: FireEye APT35 2018) ", "external_references": [{"description": "Mandiant. (2018). Mandiant M-Trends 2018. Retrieved November 17, 2024.", "source_name": "FireEye APT35 2018", "url": "https://static.carahsoft.com/concrete/files/1015/2779/3571/M-Trends-2018-Report.pdf"}], "id": "relationship--7e636340-8b64-4913-be75-a8e62f68fc91", "modified": "2026-07-31T18:48:28.721Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f9d6633a-55e6-4adc-9263-6ae080421a13", "spec_version": "2.1", "target_ref": "attack-pattern--e74de37c-a829-446c-937d-56a44f0e9306", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12910', 0, 94, '09-mitre-attack', 'retrieved', 'A128DBA5CAC62A530A4E2D4C7E871CC269D1C108EB337FD1192A3AE6E578F139', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
