VALUES ('doc-09-mitre-attack-p0-12919', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-06T21:18:18.668Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Magic Hound](https://attack.mitre.org/groups/G0059) has added a user named DefaultAccount to the Administrators and Remote Desktop Users groups.(Citation: DFIR Report APT35 ProxyShell March 2022)", "external_references": [{"description": "DFIR Report. (2022, March 21). APT35 Automates Initial Access Using ProxyShell. Retrieved May 25, 2022.", "source_name": "DFIR Report APT35 ProxyShell March 2022", "url": "https://thedfirreport.com/2022/03/21/apt35-automates-initial-access-using-proxyshell"}], "id": "relationship--8c4a2bd5-109b-4e49-ae67-a9bf02a029e7", "modified": "2026-07-31T18:48:28.919Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f9d6633a-55e6-4adc-9263-6ae080421a13", "spec_version": "2.1", "target_ref": "attack-pattern--3e6831b2-bf4c-4ae6-b328-2e7c6633b291", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12919', 0, 77, '09-mitre-attack', 'retrieved', '385DB9C32E787D0404E8078D0B8B004AFDC0807256DAACFDE30C298A6972A915', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
