VALUES ('doc-09-mitre-attack-p0-12922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-03T17:17:12.063Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Magic Hound](https://attack.mitre.org/groups/G0059) has compromised email credentials in order to steal sensitive data.(Citation: Certfa Charming Kitten January 2021)", "external_references": [{"description": "Certfa Labs. (2021, January 8). Charming Kitten’s Christmas Gift. Retrieved May 3, 2021.", "source_name": "Certfa Charming Kitten January 2021", "url": "https://blog.certfa.com/posts/charming-kitten-christmas-gift/"}], "id": "relationship--966e98f6-1460-4305-8993-57ee3f3f5654", "modified": "2026-07-31T18:48:28.984Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f9d6633a-55e6-4adc-9263-6ae080421a13", "spec_version": "2.1", "target_ref": "attack-pattern--1608f3e1-598a-42f4-a01a-2e252e81728f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12922', 0, 69, '09-mitre-attack', 'retrieved', 'E8B7D4CD480D4276200349596D9FA2B36E557A168C41E4150A6CBB3A6F17605C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
