VALUES ('doc-09-mitre-attack-p0-12946', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-04T23:30:04.892Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Magic Hound](https://attack.mitre.org/groups/G0059) used various social media channels (such as LinkedIn) as well as messaging services (such as WhatsApp) to spearphish victims.(Citation: SecureWorks Mia Ash July 2017)(Citation: Microsoft Phosphorus Mar 2019)(Citation: ClearSky Kittens Back 3 August 2020)", "external_references": [{"description": "Counter Threat Unit Research Team. (2017, July 27). The Curious Case of Mia Ash: Fake Persona Lures Middle Eastern Targets. Retrieved February 26, 2018.", "source_name": "SecureWorks Mia Ash July 2017", "url": "https://www.secureworks.com/research/the-curious-case-of-mia-ash"}, {"description": "Burt, T. (2019, March 27). New steps to protect customers from hacking. Retrieved May 27, 2020.", "source_name": "Microsoft Phosphorus Mar 2019", "url": "https://blogs.microsoft.com/on-the-issues/2019/03/27/new-steps-to-protect-customers-from-hacking/"}, {"description": "ClearSky Research Team. (2020, August 1). The Kittens Are Back in Town 3 - Charming Kitten Campaign Evolved and Deploying Spear-Phishing link by WhatsApp. Retrieved April 21, 2021.", "source_name": "ClearSky Kittens Back 3 August 2020", "url": "https://www.clearskysec.com/wp-content/uploads/2020/08/The-Kittens-are-Back-in-Town-3.pdf"}], "id": "relationship--d432f9c7-1211-4485-bac3-b35edc38d501", "modified": "2026-07-31T18:48:29.530Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--f9d6633a-55e6-4adc-9263-6ae080421a13", "spec_version": "2.1", "target_ref": "attack-pattern--f6ad61ee-65f3-4bd0-a3f5-2f0accb36317", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5