VALUES ('doc-09-mitre-attack-p0-13001', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.061Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Threat Group-3390](https://attack.mitre.org/groups/G0027) actors installed a credential logger on Microsoft Exchange servers. [Threat Group-3390](https://attack.mitre.org/groups/G0027) also leveraged the reconnaissance framework, ScanBox, to capture keystrokes.(Citation: Dell TG-3390)(Citation: Hacker News LuckyMouse June 2018)(Citation: Securelist LuckyMouse June 2018)", "external_references": [{"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}, {"description": "Khandelwal, S. (2018, June 14). Chinese Hackers Carried Out Country-Level Watering Hole Attack. Retrieved August 18, 2018.", "source_name": "Hacker News LuckyMouse June 2018", "url": "https://thehackernews.com/2018/06/chinese-watering-hole-attack.html"}, {"description": "Legezo, D. (2018, June 13). LuckyMouse hits national data center to organize country-level waterholing campaign. Retrieved August 18, 2018.", "source_name": "Securelist LuckyMouse June 2018", "url": "https://securelist.com/luckymouse-hits-national-data-center/86083/"}], "id": "relationship--6b5c6fc2-615a-46fc-80a4-9ab332159722", "modified": "2026-07-31T18:48:29.086Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fb366179-766c-4a4a-afa1-52bff1fd601c", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref