VALUES ('doc-09-mitre-attack-p0-13006', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-20T02:37:12.377Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Threat Group-3390](https://attack.mitre.org/groups/G0027) has embedded malicious code into websites to screen a potential victim''s IP address and then exploit their browser if they are of interest.(Citation: Gallagher 2015)", "external_references": [{"description": "Gallagher, S.. (2015, August 5). Newly discovered Chinese hacking group hacked 100+ websites to use as “watering holes”. Retrieved January 25, 2016.", "source_name": "Gallagher 2015", "url": "http://arstechnica.com/security/2015/08/newly-discovered-chinese-hacking-group-hacked-100-websites-to-use-as-watering-holes/"}], "id": "relationship--7acc1226-d784-448e-8aeb-7f58e343c4da", "modified": "2026-07-31T18:48:29.188Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fb366179-766c-4a4a-afa1-52bff1fd601c", "spec_version": "2.1", "target_ref": "attack-pattern--31fe0ba2-62fd-4fd9-9293-4043d84f7fe9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13006', 0, 85, '09-mitre-attack', 'retrieved', '5F15117478DF3217B222E8A298DE4733CEF5F8C1BE2E75F786CF462DAFF9AF49', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
