VALUES ('doc-09-mitre-attack-p0-13017', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-20T00:22:39.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Threat Group-3390](https://attack.mitre.org/groups/G0027) actors have used [gsecdump](https://attack.mitre.org/software/S0008) to dump credentials. They have also dumped credentials from domain controllers.(Citation: Dell TG-3390)(Citation: SecureWorks BRONZE UNION June 2017)", "external_references": [{"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}, {"description": "Counter Threat Unit Research Team. (2017, June 27). BRONZE UNION Cyberespionage Persists Despite Disclosures. Retrieved July 13, 2017.", "source_name": "SecureWorks BRONZE UNION June 2017", "url": "https://www.secureworks.com/research/bronze-union"}], "id": "relationship--a829622f-60cf-4e24-afce-fb89270e95cb", "modified": "2026-07-31T18:48:29.435Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fb366179-766c-4a4a-afa1-52bff1fd601c", "spec_version": "2.1", "target_ref": "attack-pattern--1644e709-12d2-41e5-a60f-3470991f5011", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13017', 0, 107, '09-mitre-attack', 'retrieved', 'C3646922EB8CF17366989D62731013DF1C994E8418E26D6928FFEF5DE755B465', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
