VALUES ('doc-09-mitre-attack-p0-13018', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.062Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Threat Group-3390](https://attack.mitre.org/groups/G0027) actors look for and use VPN profiles during an operation to access the network using external VPN services.(Citation: Dell TG-3390) [Threat Group-3390](https://attack.mitre.org/groups/G0027) has also obtained OWA account credentials during intrusions that it subsequently used to attempt to regain access when evicted from a victim network.(Citation: SecureWorks BRONZE UNION June 2017)", "external_references": [{"description": "Dell SecureWorks Counter Threat Unit Threat Intelligence. (2015, August 5). Threat Group-3390 Targets Organizations for Cyberespionage. Retrieved August 18, 2018.", "source_name": "Dell TG-3390", "url": "https://www.secureworks.com/research/threat-group-3390-targets-organizations-for-cyberespionage"}, {"description": "Counter Threat Unit Research Team. (2017, June 27). BRONZE UNION Cyberespionage Persists Despite Disclosures. Retrieved July 13, 2017.", "source_name": "SecureWorks BRONZE UNION June 2017", "url": "https://www.secureworks.com/research/bronze-union"}], "id": "relationship--ab6a19e4-ce00-46cd-ae83-0798471e4a4a", "modified": "2026-07-31T18:48:29.467Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fb366179-766c-4a4a-afa1-52bff1fd601c", "spec_version": "2.1", "target_ref": "attack-pattern--10d51417-ee35-4589-b1ff-b6df1c334e8d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13018', 0, 135, '09-mitre-attack', 'retrieved', '719AF4C2CB866FF65F8D62A4E05CB487069616F991C1F5474C5E47582D7E1163', 'v1', '{"source_id": 