VALUES ('doc-09-mitre-attack-p0-13042', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-17T15:07:32.378Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Threat Group-3390](https://attack.mitre.org/groups/G0027) has moved staged encrypted archives to Internet-facing servers that had previously been compromised with [China Chopper](https://attack.mitre.org/software/S0020) prior to exfiltration.(Citation: SecureWorks BRONZE UNION June 2017)", "external_references": [{"description": "Counter Threat Unit Research Team. (2017, June 27). BRONZE UNION Cyberespionage Persists Despite Disclosures. Retrieved July 13, 2017.", "source_name": "SecureWorks BRONZE UNION June 2017", "url": "https://www.secureworks.com/research/bronze-union"}], "id": "relationship--fa8d15db-498b-45f5-8cc1-bf4cf70e2e62", "modified": "2026-07-31T18:48:29.994Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fb366179-766c-4a4a-afa1-52bff1fd601c", "spec_version": "2.1", "target_ref": "attack-pattern--359b00ad-9425-420b-bba5-6de8d600cbc0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13042', 0, 83, '09-mitre-attack', 'retrieved', '279C884807D757BF188DBB0A046C53AD0EE2A9F7415756ECF6D15A4D3292A97B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
