VALUES ('doc-09-mitre-attack-p0-13172', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-02T17:19:49.632Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN13](https://attack.mitre.org/groups/G1016) has used scheduled tasks names such as `acrotyr` and `AppServicesr` to mimic the same names in a compromised network''s `C:\\Windows` directory.(Citation: Mandiant FIN13 Aug 2022)", "external_references": [{"description": "Ta, V., et al. (2022, August 8). FIN13: A Cybercriminal Threat Actor Focused on Mexico. Retrieved February 9, 2023.", "source_name": "Mandiant FIN13 Aug 2022", "url": "https://www.mandiant.com/resources/blog/fin13-cybercriminal-mexico"}], "id": "relationship--5c6b16c7-9977-4d40-b0df-75eecf350298", "modified": "2026-07-31T18:48:30.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fd66436e-4d33-450e-ac4c-f7810f1c85f4", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13172', 0, 83, '09-mitre-attack', 'retrieved', 'FFF5C3016719812F4EAEB6DDFD296F6B4C86F1B09D4507F8C29BA73F34BD946A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
