VALUES ('doc-09-mitre-attack-p0-13175', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-28T18:05:43.117Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN13](https://attack.mitre.org/groups/G1016) has created hidden files and folders within a compromised Linux system `/tmp` directory. [FIN13](https://attack.mitre.org/groups/G1016) also has used `attrib.exe` to hide gathered local host information.(Citation: Mandiant FIN13 Aug 2022)(Citation: Sygnia Elephant Beetle Jan 2022)", "external_references": [{"description": "Sygnia Incident Response Team. (2022, January 5). TG2003: ELEPHANT BEETLE UNCOVERING AN ORGANIZED FINANCIAL-THEFT OPERATION. Retrieved February 9, 2023.", "source_name": "Sygnia Elephant Beetle Jan 2022", "url": "https://web.archive.org/web/20220105132433/https://f.hubspotusercontent30.net/hubfs/8776530/Sygnia-%20Elephant%20Beetle_Jan2022.pdf"}, {"description": "Ta, V., et al. (2022, August 8). FIN13: A Cybercriminal Threat Actor Focused on Mexico. Retrieved February 9, 2023.", "source_name": "Mandiant FIN13 Aug 2022", "url": "https://www.mandiant.com/resources/blog/fin13-cybercriminal-mexico"}], "id": "relationship--6523c653-4f85-425c-a891-6df522e8c841", "modified": "2026-07-31T18:48:31.035Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fd66436e-4d33-450e-ac4c-f7810f1c85f4", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13175', 0, 119, '09-mitre-attack', 'retrieved', 'CDD946139815DF1A0FB0ECEE220F030DB7BAE51D8DE250C2BBAB012795C89E44', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_