VALUES ('doc-09-mitre-attack-p0-13178', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-03T14:51:12.881Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN13](https://attack.mitre.org/groups/G1016) has observed the victim''s software and infrastructure over several months to understand the technical process of legitimate financial transactions, prior to attempting to conduct fraudulent transactions.(Citation: Sygnia Elephant Beetle Jan 2022)", "external_references": [{"description": "Sygnia Incident Response Team. (2022, January 5). TG2003: ELEPHANT BEETLE UNCOVERING AN ORGANIZED FINANCIAL-THEFT OPERATION. Retrieved February 9, 2023.", "source_name": "Sygnia Elephant Beetle Jan 2022", "url": "https://web.archive.org/web/20220105132433/https://f.hubspotusercontent30.net/hubfs/8776530/Sygnia-%20Elephant%20Beetle_Jan2022.pdf"}], "id": "relationship--6affc901-7028-46ea-8d85-0e7d05ca9467", "modified": "2026-07-31T18:48:31.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fd66436e-4d33-450e-ac4c-f7810f1c85f4", "spec_version": "2.1", "target_ref": "attack-pattern--851e071f-208d-4c79-adc6-5974c85c78f3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13178', 0, 90, '09-mitre-attack', 'retrieved', '2BA78B5128127450DFA315CF0FC71DF423722FA249B4189A34BB6C575A34AFA4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
