VALUES ('doc-09-mitre-attack-p0-13211', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-10T22:00:27.892Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT19](https://attack.mitre.org/groups/G0073) used -W Hidden to conceal [PowerShell](https://attack.mitre.org/techniques/T1059/001) windows by setting the WindowStyle parameter to hidden. (Citation: FireEye APT19)", "external_references": [{"description": "Ahl, I. (2017, June 06). Privileges and Credentials: Phished at the Request of Counsel. Retrieved May 17, 2018.", "source_name": "FireEye APT19", "url": "https://www.fireeye.com/blog/threat-research/2017/06/phished-at-the-request-of-counsel.html"}], "id": "relationship--2e6e8722-d09d-402e-9ea8-ccf8412339d0", "modified": "2026-07-31T18:48:30.512Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--fe8796a4-2a02-41a0-9d27-7aa1e995feb6", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13211', 0, 72, '09-mitre-attack', 'retrieved', 'DBB243CC71B65D5F174F4E2926A68E0BCC0D88048D07C5A8A7C3282B67D66F74', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
