VALUES ('doc-09-mitre-attack-p0-13256', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-28T22:45:48.678Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TrickBot](https://attack.mitre.org/software/S0266) has been known to use PowerShell to download new payloads, open documents, and upload data to command and control servers. \n (Citation: Bitdefender Trickbot VNC module Whitepaper 2021)", "external_references": [{"description": "Radu Tudorica. (2021, July 12). A Fresh Look at Trickbot’s Ever-Improving VNC Module. Retrieved September 28, 2021.", "source_name": "Bitdefender Trickbot VNC module Whitepaper 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/399/Bitdefender-PR-Whitepaper-Trickbot-creat5515-en-EN.pdf"}], "id": "relationship--3a26d78f-e0cb-4a58-8d84-6d867b32f279", "modified": "2026-04-29T14:23:06.000Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00806466-754d-44ea-ad6f-0caf59cb8556", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13256', 0, 86, '09-mitre-attack', 'retrieved', 'B8A606D5461DA01B94BAA4EA01D76578840E3AE860F0EB46520C422906FD39DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
