VALUES ('doc-09-mitre-attack-p0-13258', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-01T13:41:54.436Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TrickBot](https://attack.mitre.org/software/S0266) can use secondary C2 servers for communication after establishing connectivity and relaying victim information to primary C2 servers.(Citation: Cyberreason Anchor December 2019)", "external_references": [{"description": "Dahan, A. et al. (2019, December 11). DROPPING ANCHOR: FROM A TRICKBOT INFECTION TO THE DISCOVERY OF THE ANCHOR MALWARE. Retrieved September 10, 2020.", "source_name": "Cyberreason Anchor December 2019", "url": "https://www.cybereason.com/blog/dropping-anchor-from-a-trickbot-infection-to-the-discovery-of-the-anchor-malware"}], "id": "relationship--3fa8155d-11ca-47de-902e-47e809d0ed64", "modified": "2026-04-29T14:23:06.012Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00806466-754d-44ea-ad6f-0caf59cb8556", "spec_version": "2.1", "target_ref": "attack-pattern--f24faf46-3b26-4dbb-98f2-63460498e433", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13258', 0, 85, '09-mitre-attack', 'retrieved', '8DB65CAF70751B0EDDFA97ED36F7AB0D8B9AA5311B9BF45CCDC33D0194761952', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
