VALUES ('doc-09-mitre-attack-p0-13291', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-01T14:12:52.909Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TrickBot](https://attack.mitre.org/software/S0266) has used Nt* [Native API](https://attack.mitre.org/techniques/T1106) functions to inject code into legitimate processes such as wermgr.exe .(Citation: Joe Sec Trickbot)", "external_references": [{"description": "Joe Security. (2020, July 13). TrickBot''s new API-Hammering explained. Retrieved September 30, 2021.", "source_name": "Joe Sec Trickbot", "url": "https://www.joesecurity.org/blog/498839998833561473"}], "id": "relationship--dc309013-0487-47fa-b514-71e18344a2db", "modified": "2026-04-29T14:23:06.226Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00806466-754d-44ea-ad6f-0caf59cb8556", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13291', 0, 70, '09-mitre-attack', 'retrieved', '6875C3298F0B18AB7DCDEAC3D3A0FB5633AD6CA62943E575F2A02F0A0165993F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
