VALUES ('doc-09-mitre-attack-p0-13294', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-11-28T22:03:00.924Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "TrickBot has used a hidden VNC (hVNC) window to monitor the victim and collect information stealthily.(Citation: Emotet Deploys TrickBot)", "external_references": [{"description": "Cybereason Nocturnus. (n.d.). Triple Threat: Emotet Deploys TrickBot to Steal Data & Spread Ryuk. Retrieved November 28, 2023.", "source_name": "Emotet Deploys TrickBot", "url": "https://www.cybereason.com/blog/research/triple-threat-emotet-deploys-trickbot-to-steal-data-spread-ryuk-ransomware#:~:text=TrickBot%20uses%20a%20hidden%20VNC,desktop%20without%20the%20victim%20noticing"}], "id": "relationship--e83a16d0-70b7-415c-8b3f-bdbb89f10455", "modified": "2026-04-29T14:23:06.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00806466-754d-44ea-ad6f-0caf59cb8556", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13294', 0, 74, '09-mitre-attack', 'retrieved', 'F23BBEC19984505DEF41D6489A0B75161F566FB81B987A2E30FDF8258610A3C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
