VALUES ('doc-09-mitre-attack-p0-13298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T19:15:06.328Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TrickBot](https://attack.mitre.org/software/S0266) can obtain passwords stored in files from web browsers such as Chrome, Firefox, Internet Explorer, and Microsoft Edge, sometimes using [esentutl](https://attack.mitre.org/software/S0404).(Citation: Trend Micro Trickbot Nov 2018)(Citation: Cyberreason Anchor December 2019)(Citation: Bitdefender Trickbot VNC module Whitepaper 2021)", "external_references": [{"description": "Anthony, N., Pascual, C.. (2018, November 1). Trickbot Shows Off New Trick: Password Grabber Module. Retrieved November 16, 2018.", "source_name": "Trend Micro Trickbot Nov 2018", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/trickbot-shows-off-new-trick-password-grabber-module/"}, {"description": "Dahan, A. et al. (2019, December 11). DROPPING ANCHOR: FROM A TRICKBOT INFECTION TO THE DISCOVERY OF THE ANCHOR MALWARE. Retrieved September 10, 2020.", "source_name": "Cyberreason Anchor December 2019", "url": "https://www.cybereason.com/blog/dropping-anchor-from-a-trickbot-infection-to-the-discovery-of-the-anchor-malware"}, {"description": "Radu Tudorica. (2021, July 12). A Fresh Look at Trickbot’s Ever-Improving VNC Module. Retrieved September 28, 2021.", "source_name": "Bitdefender Trickbot VNC module Whitepaper 2021", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/399/Bitdefender-PR-Whitepaper-Trickbot-creat5515-en-EN.pdf"}], "id": "relationship--f0dd2703-4846-47b5-a8d8-471f70f9968e", "modified": "2026-04-29T14:23:06.253Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00806466-754d-44ea-ad6f-0caf59cb8556", "spec_version": "2.1", "target_ref": "attack-pattern--58a3e6aa-4453-4cc8-a51f-4befe80b31a8