VALUES ('doc-09-mitre-attack-p0-13303', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-15T18:56:36.733Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TrickBot](https://attack.mitre.org/software/S0266) utilizes EternalBlue and EternalRomance exploits for lateral movement in the modules wormwinDll, wormDll, mwormDll, nwormDll, tabDll.(Citation: ESET Trickbot Oct 2020)", "external_references": [{"description": "Boutin, J. (2020, October 12). ESET takes part in global operation to disrupt Trickbot. Retrieved March 15, 2021.", "source_name": "ESET Trickbot Oct 2020", "url": "https://www.welivesecurity.com/2020/10/12/eset-takes-part-global-operation-disrupt-trickbot/"}], "id": "relationship--e56f602c-ec9f-46f0-a52f-45b90220314e", "modified": "2026-08-04T20:30:56.297Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00806466-754d-44ea-ad6f-0caf59cb8556", "spec_version": "2.1", "target_ref": "attack-pattern--9db0cf3a-a3c9-4012-8268-123b9db6fd82", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13303', 0, 77, '09-mitre-attack', 'retrieved', '7F822B27EC151AD75D73280E6E872EA1ACFE459E52D997533A975E59D7F869FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
