VALUES ('doc-09-mitre-attack-p0-13306', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-19T20:32:20.200Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[cd00r](https://attack.mitre.org/software/S1204) can use the libpcap library to monitor captured packets for specifc sequences.(Citation: Hartrell cd00r 2002)", "external_references": [{"description": "Hartrell, Greg. (2002, August). Get a handle on cd00r: The invisible backdoor. Retrieved October 13, 2018.", "source_name": "Hartrell cd00r 2002", "url": "https://www.giac.org/paper/gcih/342/handle-cd00r-invisible-backdoor/103631"}], "id": "relationship--ba8a5719-2e23-4bdf-9029-59a3babd66f6", "modified": "2026-04-29T14:23:06.179Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--00936d7a-451d-4a9c-88fc-05b141aa2d3f", "spec_version": "2.1", "target_ref": "attack-pattern--3257eb21-f9a7-4430-8de1-d8b6e288f529", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13306', 0, 69, '09-mitre-attack', 'retrieved', '9AD067F334AEE164B3C7F006BC53AD52CACAF2F8C1968BB7A67A5A8387194554', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
