VALUES ('doc-09-mitre-attack-p0-13353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-27T19:26:38.248Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BLINDINGCAN](https://attack.mitre.org/software/S0520) has used AES and XOR to decrypt its DLLs.(Citation: US-CERT BLINDINGCAN Aug 2020)", "external_references": [{"description": "US-CERT. (2020, August 19). MAR-10295134-1.v1 – North Korean Remote Access Trojan: BLINDINGCAN. Retrieved August 19, 2020.", "source_name": "US-CERT BLINDINGCAN Aug 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-232a"}], "id": "relationship--ea027248-40a2-403b-a0e9-748bdc8c5667", "modified": "2026-04-29T14:23:06.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--01dbc71d-0ee8-420d-abb4-3dfb6a4bf725", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13353', 0, 68, '09-mitre-attack', 'retrieved', '7862BA82025B2ED1E1F057ECF733495B57A615294220C7B9DDE6F11DBCD1F76E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
