VALUES ('doc-09-mitre-attack-p0-13354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-05T17:56:30.694Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Ninja](https://attack.mitre.org/software/S1100) payload is XOR encrypted and compressed.(Citation: Kaspersky ToddyCat Check Logs October 2023) [Ninja](https://attack.mitre.org/software/S1100) has also XORed its configuration data with a constant value of `0xAA`.(Citation: Kaspersky ToddyCat June 2022)(Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"description": "Dedola, G. (2022, June 21). APT ToddyCat. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat June 2022", "url": "https://securelist.com/toddycat/106799/"}, {"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "relationship--18b6546b-90a1-4f70-8faf-505810bba9a6", "modified": "2026-04-29T14:23:05.938Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--023254de-caaf-4a05-b2c7-e4e2f283f7a5", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13354', 0, 113, '09-mitre-attack', 'retrieved', 'FD4174B395627A5579F6CE1EA7348ED456D5CBBC15EC610BA17D74D7AC0D7C5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
