VALUES ('doc-09-mitre-attack-p0-13382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-14T20:21:22.614Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145) gathers victim network information through commands such as ipconfig and ipconfig /all .(Citation: Zscaler Pikabot 2023)", "external_references": [{"description": "Brett Stone-Gross & Nikolaos Pantazopoulos. (2023, May 24). Technical Analysis of Pikabot. Retrieved July 12, 2024.", "source_name": "Zscaler Pikabot 2023", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-pikabot"}], "id": "relationship--05381a55-01d2-4c75-9a2b-504eff1b606a", "modified": "2026-04-29T14:23:05.910Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13382', 0, 70, '09-mitre-attack', 'retrieved', '9C13C50ED1747C29326AFB770FD74F8A874E7D340D97B7B3CF5FBD518173C9E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
