INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-13388', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-14T21:30:48.464Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Earlier [Pikabot](https://attack.mitre.org/software/S1145) variants use a custom encryption procedure leveraging multiple mechanisms including AES with multiple rounds of Base64 encoding for its command and control communication.(Citation: Zscaler Pikabot 2023) Later [Pikabot](https://attack.mitre.org/software/S1145) variants eliminate the use of AES and instead use RC4 encryption for transmitted information.(Citation: Elastic Pikabot 2024)", "external_references": [{"description": "Brett Stone-Gross & Nikolaos Pantazopoulos. (2023, May 24). Technical Analysis of Pikabot. Retrieved July 12, 2024.", "source_name": "Zscaler Pikabot 2023", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-pikabot"}, {"description": "Daniel Stepanic & Salim Bitam. (2024, February 23). PIKABOT, I choose you!. Retrieved July 12, 2024.", "source_name": "Elastic Pikabot 2024", "url": "https://www.elastic.co/security-labs/pikabot-i-choose-you"}], "id": "relationship--63113486-c2a1-4a83-8d49-2065f972f83f", "modified": "2026-04-29T14:23:06.060Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13388', 0, 123, '09-mitre-attack', 'retrieved', '1C31A27A25EC99F831A567C783B038D6B7EE430D8CCE48D6B4C7B063FF7B71AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
