VALUES ('doc-09-mitre-attack-p0-13389', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-16T18:12:09.758Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During the initial [Pikabot](https://attack.mitre.org/software/S1145) command and control check-in, [Pikabot](https://attack.mitre.org/software/S1145) will transmit collected system information encrypted using RC4.(Citation: Elastic Pikabot 2024)", "external_references": [{"description": "Daniel Stepanic & Salim Bitam. (2024, February 23). PIKABOT, I choose you!. Retrieved July 12, 2024.", "source_name": "Elastic Pikabot 2024", "url": "https://www.elastic.co/security-labs/pikabot-i-choose-you"}], "id": "relationship--69cbfe97-c712-4ffe-ac32-b1ce605e516c", "modified": "2026-04-29T14:23:06.069Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13389', 0, 73, '09-mitre-attack', 'retrieved', '8723AC14ADFE43DA3338B7C61E246D8D40A3077B8B7ED22421F4E7FF93ED3412', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
