INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-13391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-12T19:16:59.559Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145) uses native Windows APIs to determine if the process is being debugged and analyzed, such as `CheckRemoteDebuggerPresent`, `NtQueryInformationProcess`, `ProcessDebugPort`, and `ProcessDebugFlags`.(Citation: Zscaler Pikabot 2023) Other [Pikabot](https://attack.mitre.org/software/S1145) variants populate a global list of Windows API addresses from the `NTDLL` and `KERNEL32` libraries, and references these items instead of calling the API items to obfuscate execution.(Citation: Elastic Pikabot 2024)", "external_references": [{"description": "Brett Stone-Gross & Nikolaos Pantazopoulos. (2023, May 24). Technical Analysis of Pikabot. Retrieved July 12, 2024.", "source_name": "Zscaler Pikabot 2023", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-pikabot"}, {"description": "Daniel Stepanic & Salim Bitam. (2024, February 23). PIKABOT, I choose you!. Retrieved July 12, 2024.", "source_name": "Elastic Pikabot 2024", "url": "https://www.elastic.co/security-labs/pikabot-i-choose-you"}], "id": "relationship--6e9b093c-a8c4-4da8-ac07-3e019ce9e16e", "modified": "2026-04-29T14:23:06.076Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13391', 0, 134, '09-mitre-attack', 'retrieved', '8C0B54A5DFCC87D4C1FA71C919820F6CE919A25FBDA31771EC7DB04E18381F33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
