INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-13396', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-16T18:51:20.093Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145) uses base64 encoding in conjunction with symmetric encryption mechanisms to obfuscate command and control communications.(Citation: Zscaler Pikabot 2023)(Citation: Elastic Pikabot 2024)", "external_references": [{"description": "Brett Stone-Gross & Nikolaos Pantazopoulos. (2023, May 24). Technical Analysis of Pikabot. Retrieved July 12, 2024.", "source_name": "Zscaler Pikabot 2023", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-pikabot"}, {"description": "Daniel Stepanic & Salim Bitam. (2024, February 23). PIKABOT, I choose you!. Retrieved July 12, 2024.", "source_name": "Elastic Pikabot 2024", "url": "https://www.elastic.co/security-labs/pikabot-i-choose-you"}], "id": "relationship--b44a5877-4cd1-4a5c-b2ea-d1078da36cc2", "modified": "2026-04-29T14:23:06.171Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--04fd5427-79c7-44ea-ae13-11b24778ff1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13396', 0, 98, '09-mitre-attack', 'retrieved', '2BCA8AE81776E4E0520D377565868DC70F82AF765CF0947B8A145799928241F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
