VALUES ('doc-09-mitre-attack-p0-13399', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-12T19:26:24.140Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145), following payload decryption, creates a process hard-coded into the dropped (e.g., WerFault.exe) and injects the decrypted core modules into it.(Citation: Zscaler Pikabot 2023)", "external_references": [{"description": "Brett Stone-Gross & Nikolaos Pantazopoulos. (2023, May 24). Technical Analysis of Pikabot. Retrieved July 12, 2024.", "source_name": "Zscaler Pikabot 2023", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-pikabot"}], "id": "relationship--d21794dc-278a-41c5-9707-17113f261d1d", "modified": "2026-04-29T14:23:06.213Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--806a49c4-970d-43f9-9acc-ac0ee11e6662", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13399', 0, 77, '09-mitre-attack', 'retrieved', '565CB320E53FD7D2B709639C36E4140351260C8836EAE7DF8140182C1AAF5617', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
