VALUES ('doc-09-mitre-attack-p0-13402', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-12T19:18:36.846Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pikabot](https://attack.mitre.org/software/S1145) performs a variety of system checks to determine if it is running in an analysis environment or sandbox, such as checking the number of processors (must be greater than two), and the amount of RAM (must be greater than 2GB).(Citation: Elastic Pikabot 2024)", "external_references": [{"description": "Daniel Stepanic & Salim Bitam. (2024, February 23). PIKABOT, I choose you!. Retrieved July 12, 2024.", "source_name": "Elastic Pikabot 2024", "url": "https://www.elastic.co/security-labs/pikabot-i-choose-you"}], "id": "relationship--ed8cf613-63f8-4f50-be4d-f73aba6a3467", "modified": "2026-04-29T14:23:06.248Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--02739f57-7585-4319-acd3-794ae8ff3a70", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13402', 0, 97, '09-mitre-attack', 'retrieved', '5883AF9C105E1C43AAAC66A60339D305812F8AFE2A95D0E4E2AD319E2447668C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
